use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: the conv history leaves the buffer BEFORE the buffer is consumed
        // in place — per-tile 3-row packs are O(tiles), the register window
        // replaces hot-loop history reads, tiles are independent after the
        // pack, and the phase law (pack all, then scan) is what makes the
        // in-place form correct. ──
        KernelRule {
            rule_id: "tile-history-packed-in-place-register-window-conv-scan".to_string(),
            gpu_concept: "MECHANISM (per-tile packed conv history feeding an in-place register-window tile scan; category A — memory access/staging): the prefill causal conv1d materializes NO padded buffer. DeltaNetConvPack saves only the tile frontier — the pack kernel's own two-line law, verbatim (conv_pack.metal:6-7): '// Saves the KERNEL_SIZE - 1 rows before each token tile, which the in-place DeltaNetConvScan overwrites:' + '// packed[tile, tap] = row (tile * tile_tokens - TAPS + tap) of [conv state ++ x].' — so the scratch is [num_tiles, KERNEL_SIZE-1, conv_dim]: O(TILES), constant in the token axis (tile 0's history is the conv state; tile n's is tile n-1's last three RAW input rows), where the old Conv1dPack filled [state_stride + suffix_len, row_stride] — the history AND every input row — and the scan re-read every tap from it (the removed hunk's grid, verbatim: 'const uint row_idx AXIS(state_stride + suffix_len, 1)'; the new grid, verbatim (conv_pack.metal:24): 'const uint tile_idx AXIS(suffix_len.div_ceil(tile_tokens), 1)'). DeltaNetConvScan then consumes the packed rows with a REGISTER window while writing IN PLACE — the kernel's own contract, verbatim (conv_scan.metal:7-8): '// Causal conv1d + SiLU, in place on in_proj. A thread owns CHANNELS channels of one token tile; its first window' + '// comes from DeltaNetConvPack, so tiles are independent. The last tile writes state_out.' THE WINDOW IS REGISTERS, verbatim (conv_scan.metal:78): 'float window[TAPS][CHANNELS];' — the tap fold runs fma against the window then the in_proj sample (conv_scan.metal:98-101: 'acc = fma(weights[j * KERNEL_SIZE + tap], window[tap][j], acc);' + 'acc = fma(weights[j * KERNEL_SIZE + TAPS], rows[r][j], acc);'), the output stores back over the SAME in_proj row (conv_scan.metal:103: 'store_channels(in_proj + (token + r) * size_t(out_stride) + first_channel, outputs);'), and the window slides by register copy, never a buffer read (conv_scan.metal:104-110: 'window[tap][j] = window[tap + 1][j];' + 'window[TAPS - 1][j] = rows[r][j];'). THE PHASE LAW (load-bearing, in-place-only): EVERY tile's history must be packed BEFORE ANY tile overwrites the input — tile n's pack reads tile n-1's raw rows, which tile n-1's in-place scan has already replaced with SiLU outputs; after the pack, tiles are INDEPENDENT: any visit order is bit-identical, which is what lets the launch parallelize them (conv_scan.metal:59: 'const uint tile_idx AXIS(suffix_len.div_ceil(tile_tokens), 4)' — four concurrent tile groups; the CPU mirror names the same law, conv_scan.rs:7-8: '// Multi-token causal conv1d with SiLU for DeltaNet, in place on in_proj. Each token tile starts from its packed rows (see' + '// DeltaNetConvPack), so tiles are independent; the last tile writes the new conv state.' and slides 'window.remove(0);' + 'window.push(sample);' at conv_scan.rs:55-56). THE HOST FACE: the scratch allocation itself shrank, verbatim (delta_net.rs:556-559): 'let conv_tile_tokens = batch_dim.size().div_ceil(CONV_TILES).max(CONV_MIN_TILE_TOKENS);' + 'debug_assert!(conv_tile_tokens >= self.kernel_size - 1);' + 'allocate_scratch_for_shape(&[CONV_TILES, self.kernel_size - 1, self.conv_dim], INNER_DATA_TYPE)' against the removed hunk '[batch_dim.size() + self.kernel_size - 1, self.total_proj_dim]' — and the tile knobs are named constants, verbatim (delta_net.rs:33-35): '// Prefill conv: up to CONV_TILES token tiles of at least CONV_MIN_TILE_TOKENS (correctness needs >= KERNEL_SIZE - 1).' + 'const CONV_TILES: u32 = 16;' + 'const CONV_MIN_TILE_TOKENS: u32 = 16;'. KERNEL_SIZE is a constexpr with its own variant axis ('VARIANTS(KERNEL_SIZE, 4)' at conv_pack.metal:14; the host refuses anything else, delta_net.rs:172: 'kernel_size must be 4, got {}'), and the vec4 channel path pins the row stride (delta_net.rs:194: 'if !total_proj_dim.is_multiple_of(8)'). Commit-message numbers (M5 Max, SOURCE-REPORTED): 'Conv: `DeltaNetConvPack` copies only each tile's 3 previous rows; `DeltaNetConvScan` runs 16 tiles in place with a register window. 460 → 47 µs (T=1024).' — note 16 tiles in place is the CONV_TILES constant, not a capability claim. DECISION CONTENT: (a) the scratch is O(TILES) — constant in suffix_len, the packed shape rides the tile count; (b) pack ALL tiles before ANY in-place write — the pack is a dependency-frontier snapshot for destructive consumption, not an optimization; (c) post-pack tile independence: visit order is free, the grid exploits it (AXIS(..., 4)); (d) the hot loop never reads a history buffer — the window slides in registers; (e) only the last tile writes state_out, from its window — the old form's separate state pass re-read the buffer tail. CLASS SIGNATURE: a causal sliding-window kernel whose input buffer is ALSO its output buffer — the tap history must leave the buffer before the buffer is consumed destructively. REGIME: prefill-sized multi-token causal convs / short-window recurrences (small K, here 4) where the conv output overwrites the projected input rows in place. ANTI-REGIME: read-only input consumers (a plain halo pre-pass suffices — the kinship's ds4 rule); K large enough that per-tile history exceeds the register window budget; single-token decode (the in-place state slide owns that shape). KINSHIP (do not double-count): window-recurrence-halo-snapshot-block-parallel (gpu_35) owns the HALO-SNAPSHOT-FOR-PARALLELISM axis on a READ-ONLY input (blocks keep reading raw rows from the original buffer; the full-input snapshot variant measured the loser) — THIS owns the DESTRUCTIVE-CONSUMPTION face: the pack exists BECAUSE the scan overwrites the input, and the register window replaces hot-loop buffer reads outright. fused-conv-state-shift-dot-silu (gpu_02) owns the decode-step single-token in-place slide (the state IS the window, global-persistent across steps); THIS is the multi-token prefill tile form of the same in-place discipline. The zero-pad elimination pole (the pad-in-read rider on dtype-native-source-read-with-shared-admission-predicate, entries_gpu_51) is ADJACENT-NOT-COVERING: that pole removes padding rows that never carry data ('the zero rows never exist as a buffer'); THIS packs REAL history rows and bounds them per tile. stacked-gate-up-single-launch-split-store (gpu_106) is adjacent launch-count-by-layout (copy elision) — HERE the launch count is unchanged (pack + scan stay two kernels); the win is the buffer's SHAPE, not a launch. verify-ubatch-full-prestage-lane-token-gate-broadcast (gpu_105) stages the WHOLE short window into shared — THIS stages ONLY the tap rows, never the tile's own tokens (they stay in in_proj, consumed in place). NOVEL (grep 'conv history|packed history|history rows|register window|tile_tokens|CONV_TILES|window.remove' over both corpora at claim): zero owners of the pack-then-destructive-scan pair — the conv hits route to the decode slide (gpu_02) and the read-only halo (gpu_35), neither of which overwrites its input. NotBenchable here (M5 Max numbers are source-reported on different silicon — never our bench claim; the instruments are the chunked-vs-recurrent parity fixtures and the bit pins). Source: trymirai/uzu @ e744e7cf4dc52e14f127d201aa04d24efb07a0c7 (MIT) — backends/metal/kernel/gdn/conv_pack.metal:6-33, conv_scan.metal:7-110, backends/cpu/kernel/gdn/conv_scan.rs:7-56, encodable_block/mixer/delta_net.rs:33-35,172,556-559 at e744e7c. Batch 259 / Plan 263 / Research 295.".to_string(),
            ref_shape: "// naive: the padded-history conv1d — the pack kernel materializes ONE\n// padded buffer [state_stride + suffix_len, row_stride] holding the conv\n// state AND every input token row, then the scan kernel re-reads every\n// tap of every token from that buffer and the new state comes from the\n// buffer's tail rows. The scratch scales with the token axis and the\n// input rows are written twice (once as x, once into the padded buffer).\nconst K: usize = 4; // kernel_size\nconst TAPS: usize = K - 1; // 3 history rows\nconst C: usize = 8; // conv_dim\nconst N: usize = 64; // suffix_len tokens\n\nfn silu(a: f32) -> f32 {\n    a / (1.0 + (-a).exp())\n}\n\n// dyadic weights + integer samples keep every product and sum exact in f32,\n// so the optimized form's register window is bit-comparable to this buffer\n// walk (the only transcendental is SiLU, called on identical bits)\nfn weight(ch: usize, tap: usize) -> f32 {\n    const TABLE: [f32; K] = [1.0, 0.5, 0.25, -0.5];\n    TABLE[(ch + tap) % K]\n}\n\nfn sample(token: usize, ch: usize) -> f32 {\n    (((token * 7 + ch * 3) % 11) as i32 - 5) as f32\n}\n\nfn state(ch: usize, tap: usize) -> f32 {\n    (((ch * 5 + tap * 2) % 7) as i32 - 3) as f32\n}\n\n/// the old Conv1dPack: fill the padded buffer, history rows first\nfn pack_padded(padded: &mut Vec<f32>) -> usize {\n    padded.clear();\n    padded.resize((TAPS + N) * C, 0.0);\n    let mut writes = 0;\n    for row in 0..TAPS + N {\n        for ch in 0..C {\n            padded[row * C + ch] = if row < TAPS {\n                state(ch, row)\n            } else {\n                sample(row - TAPS, ch)\n            };\n            writes += 1;\n        }\n    }\n    writes\n}\n\n/// the old DeltaNetConvScan: every tap of every token read back from the\n/// padded buffer; the state update re-reads the buffer's tail\nfn scan_padded(padded: &[f32]) -> ([[f32; C]; N], [[f32; TAPS]; C], usize) {\n    let mut w_tab = [[0.0f32; K]; C];\n    for ch in 0..C {\n        for tap in 0..K {\n            w_tab[ch][tap] = weight(ch, tap);\n        }\n    }\n    let mut out = [[0.0f32; C]; N];\n    let mut reads = 0;\n    for token in 0..N {\n        for ch in 0..C {\n            let mut acc = 0.0f32;\n            for tap in 0..K {\n                acc += w_tab[ch][tap] * padded[(token + tap) * C + ch];\n                reads += 1;\n            }\n            out[token][ch] = silu(acc);\n        }\n    }\n    let mut state_out = [[0.0f32; TAPS]; C];\n    for ch in 0..C {\n        for tap in 0..TAPS {\n            state_out[ch][tap] = padded[(N + tap) * C + ch];\n            reads += 1;\n        }\n    }\n    (out, state_out, reads)\n}\n\n#[test]\nfn the_padded_scratch_scales_with_the_token_axis() {\n    let mut padded = Vec::new();\n    let writes = pack_padded(&mut padded);\n    assert_eq!(padded.len(), (TAPS + N) * C, \"history AND every input row materialized\");\n    assert_eq!(writes, padded.len());\n    // the buffer is a function of suffix_len: doubling the token axis\n    // doubles the history-scratch burden (the optimized lane's packed\n    // buffer is constant in the token axis)\n    assert_eq!((TAPS + 2 * N) * C, 2 * (TAPS + N) * C - TAPS * C);\n    assert!(TAPS * C > 0);\n}\n\n#[test]\nfn the_naive_scan_rereads_every_tap_from_the_buffer() {\n    let mut padded = Vec::new();\n    pack_padded(&mut padded);\n    let (out, state_out, reads) = scan_padded(&padded);\n    assert_eq!(reads, N * K * C + C * TAPS, \"every tap re-read from the padded buffer\");\n    // the state update is the buffer's tail: the last TAPS samples\n    for ch in 0..C {\n        for tap in 0..TAPS {\n            assert_eq!(state_out[ch][tap], sample(N - TAPS + tap, ch));\n        }\n    }\n    // spot-check one exact accumulation: tap order 0,1,2,3\n    let mut acc = 0.0f32;\n    for tap in 0..K {\n        acc += weight(0, tap) * padded[(3 + tap) * C];\n    }\n    assert_eq!(out[3][0], silu(acc));\n}\n".to_string(),
            opt_pattern: "// optimized: DeltaNetConvPack copies ONLY each tile's 3 previous rows into\n// packed [num_tiles, K-1, C] — O(tiles), constant in the token axis — and\n// DeltaNetConvScan runs the tiles IN PLACE on in_proj: a register window\n// starts from the tile's packed rows and slides through the tile's tokens,\n// so no tile ever reads another tile's OUTPUT rows. The load-bearing phase\n// law: every tile's history is packed BEFORE any tile overwrites the input\n// (tile n's history is tile n-1's raw rows, which the in-place scan of\n// tile n-1 has already replaced with SiLU outputs).\nconst K: usize = 4; // kernel_size (constexpr 4 in the source)\nconst TAPS: usize = K - 1;\nconst C: usize = 8; // conv_dim\nconst N: usize = 64; // suffix_len tokens\nconst TILES: usize = 4; // CONV_TILES in the source (16); fixture shrinks it\n\n// shared deterministic helpers (verbatim from ref_shape so the fixture\n// compiles and runs standalone)\nfn silu(a: f32) -> f32 {\n    a / (1.0 + (-a).exp())\n}\n\nfn weight(ch: usize, tap: usize) -> f32 {\n    const TABLE: [f32; K] = [1.0, 0.5, 0.25, -0.5];\n    TABLE[(ch + tap) % K]\n}\n\nfn sample(token: usize, ch: usize) -> f32 {\n    (((token * 7 + ch * 3) % 11) as i32 - 5) as f32\n}\n\nfn state(ch: usize, tap: usize) -> f32 {\n    (((ch * 5 + tap * 2) % 7) as i32 - 3) as f32\n}\n\nfn tile_tokens(n: usize) -> usize {\n    n.div_ceil(TILES)\n}\n\nfn w_tab() -> [[f32; K]; C] {\n    let mut t = [[0.0f32; K]; C];\n    for ch in 0..C {\n        for tap in 0..K {\n            t[ch][tap] = weight(ch, tap);\n        }\n    }\n    t\n}\n\n// the ref_shape naive form, re-declared so the bit-equality check is local\nfn pack_padded(padded: &mut Vec<f32>) -> usize {\n    padded.clear();\n    padded.resize((TAPS + N) * C, 0.0);\n    let mut writes = 0;\n    for row in 0..TAPS + N {\n        for ch in 0..C {\n            padded[row * C + ch] = if row < TAPS {\n                state(ch, row)\n            } else {\n                sample(row - TAPS, ch)\n            };\n            writes += 1;\n        }\n    }\n    writes\n}\n\nfn scan_padded(padded: &[f32]) -> ([[f32; C]; N], [[f32; TAPS]; C]) {\n    let w_t = w_tab();\n    let mut out = [[0.0f32; C]; N];\n    for token in 0..N {\n        for ch in 0..C {\n            let mut acc = 0.0f32;\n            for tap in 0..K {\n                acc += w_t[ch][tap] * padded[(token + tap) * C + ch];\n            }\n            out[token][ch] = silu(acc);\n        }\n    }\n    let mut state_out = [[0.0f32; TAPS]; C];\n    for ch in 0..C {\n        for tap in 0..TAPS {\n            state_out[ch][tap] = padded[(N + tap) * C + ch];\n        }\n    }\n    (out, state_out)\n}\n\n/// DeltaNetConvPack: packed[tile, tap] = row (tile*tile_tokens - TAPS + tap)\n/// of [conv state ++ x]. Tile 0's history is the conv state; tile n's\n/// history is the last TAPS raw input rows of tile n-1.\nfn pack_tiles(packed: &mut Vec<f32>, n: usize) -> usize {\n    let tt = tile_tokens(n);\n    packed.clear();\n    packed.resize(TILES * TAPS * C, 0.0);\n    let mut writes = 0;\n    for tile in 0..n.div_ceil(tt) {\n        for tap in 0..TAPS {\n            for ch in 0..C {\n                let value = if tile == 0 {\n                    state(ch, tap)\n                } else {\n                    sample(tile * tt - TAPS + tap, ch)\n                };\n                packed[(tile * TAPS + tap) * C + ch] = value;\n                writes += 1;\n            }\n        }\n    }\n    writes\n}\n\n/// DeltaNetConvScan: in place on in_proj. The window is the tile's packed\n/// rows and slides in registers; only the last tile writes the new state.\n/// `order` selects the tile visit order — tiles are independent, so any\n/// order is bit-identical.\nfn scan_tiles(\n    packed: &[f32],\n    in_proj: &mut [[f32; C]; 128],\n    w_t: &[[f32; K]; C],\n    state_out: &mut [[f32; TAPS]; C],\n    n: usize,\n    order: &[usize],\n    log: &mut Vec<&'static str>,\n) -> usize {\n    let tt = tile_tokens(n);\n    let mut writes = 0;\n    log.push(\"packed_all\");\n    for &tile in order {\n        let begin = tile * tt;\n        let end = (begin + tt).min(n);\n        for ch in 0..C {\n            let mut window = [0.0f32; TAPS];\n            for tap in 0..TAPS {\n                window[tap] = packed[(tile * TAPS + tap) * C + ch];\n            }\n            for token in begin..end {\n                let s = in_proj[token][ch];\n                let mut acc = 0.0f32;\n                for tap in 0..TAPS {\n                    acc += w_t[ch][tap] * window[tap];\n                }\n                acc += w_t[ch][TAPS] * s;\n                in_proj[token][ch] = silu(acc);\n                writes += 1;\n                for tap in 0..TAPS - 1 {\n                    window[tap] = window[tap + 1];\n                }\n                window[TAPS - 1] = s;\n            }\n            if end == n {\n                for tap in 0..TAPS {\n                    state_out[ch][tap] = window[tap];\n                }\n            }\n        }\n    }\n    log.push(\"scanned\");\n    writes\n}\n\n/// the WRONG phase order: pack each tile only as the scan reaches it —\n/// tile n's pack reads in_proj rows tile n-1 has already overwritten with\n/// SiLU outputs, so the history is corrupted. Legal in a read-only halo\n/// design, illegal in the in-place design.\nfn scan_tiles_interleaved_wrong(\n    in_proj: &mut [[f32; C]; 128],\n    w_t: &[[f32; K]; C],\n    state_out: &mut [[f32; TAPS]; C],\n    n: usize,\n) {\n    let tt = tile_tokens(n);\n    for tile in 0..n.div_ceil(tt) {\n        // full global layout; only this tile's rows are filled — and they\n        // are filled STALE: from in_proj rows the previous tile's in-place\n        // scan already replaced with SiLU outputs\n        let mut packed = vec![0.0f32; TILES * TAPS * C];\n        for tap in 0..TAPS {\n            for ch in 0..C {\n                let value = if tile == 0 {\n                    state(ch, tap)\n                } else {\n                    in_proj[tile * tt - TAPS + tap][ch] // STALE: already silu\n                };\n                packed[(tile * TAPS + tap) * C + ch] = value;\n            }\n        }\n        let _ = scan_tiles(&packed, in_proj, w_t, state_out, (tile + 1) * tt, &[tile], &mut Vec::new());\n    }\n}\n\n#[test]\nfn the_tile_form_reproduces_the_padded_bits() {\n    let mut padded = Vec::new();\n    pack_padded(&mut padded);\n    let (ref_out, ref_state) = scan_padded(&padded);\n\n    let mut packed = Vec::new();\n    pack_tiles(&mut packed, N);\n    let w_t = w_tab();\n    let mut in_proj = [[0.0f32; C]; 128];\n    for token in 0..N {\n        for ch in 0..C {\n            in_proj[token][ch] = sample(token, ch);\n        }\n    }\n    let mut state_out = [[0.0f32; TAPS]; C];\n    let mut log = Vec::new();\n    let writes = scan_tiles(&packed, &mut in_proj, &w_t, &mut state_out, N, &[0, 1, 2, 3], &mut log);\n    for token in 0..N {\n        for ch in 0..C {\n            assert_eq!(in_proj[token][ch].to_bits(), ref_out[token][ch].to_bits(), \"row {token} col {ch} moved bits\");\n        }\n    }\n    for ch in 0..C {\n        for tap in 0..TAPS {\n            assert_eq!(state_out[ch][tap].to_bits(), ref_state[ch][tap].to_bits(), \"state moved bits\");\n        }\n    }\n    assert_eq!(writes, N * C, \"the scan writes each row once, in place\");\n    assert_eq!(log, vec![\"packed_all\", \"scanned\"], \"every pack precedes every in-place write\");\n}\n\n#[test]\nfn the_packed_scratch_is_constant_in_the_token_axis() {\n    let mut packed_small = Vec::new();\n    let w_small = pack_tiles(&mut packed_small, N);\n    let mut packed_big = Vec::new();\n    let w_big = pack_tiles(&mut packed_big, 2 * N);\n    assert_eq!(packed_small.len(), TILES * TAPS * C, \"O(tiles): [num_tiles, K-1, C]\");\n    assert_eq!(packed_small.len(), packed_big.len(), \"doubling suffix_len moves no scratch\");\n    assert_eq!(w_small, w_big);\n    assert!(w_small * 4 < (TAPS + N) * C, \"the pack writes a fraction of the padded form\");\n}\n\n#[test]\nfn tiles_are_independent_any_visit_order_is_bit_identical() {\n    let mut packed = Vec::new();\n    pack_tiles(&mut packed, N);\n    let w_t = w_tab();\n    let mut a = [[0.0f32; C]; 128];\n    let mut b = [[0.0f32; C]; 128];\n    for token in 0..N {\n        for ch in 0..C {\n            a[token][ch] = sample(token, ch);\n            b[token][ch] = sample(token, ch);\n        }\n    }\n    let mut sa = [[0.0f32; TAPS]; C];\n    let mut sb = [[0.0f32; TAPS]; C];\n    scan_tiles(&packed, &mut a, &w_t, &mut sa, N, &[0, 1, 2, 3], &mut Vec::new());\n    scan_tiles(&packed, &mut b, &w_t, &mut sb, N, &[3, 1, 0, 2], &mut Vec::new());\n    for token in 0..N {\n        for ch in 0..C {\n            assert_eq!(a[token][ch].to_bits(), b[token][ch].to_bits());\n        }\n    }\n    for ch in 0..C {\n        for tap in 0..TAPS {\n            assert_eq!(sa[ch][tap].to_bits(), sb[ch][tap].to_bits(), \"the state rides the last tile, order-free\");\n        }\n    }\n}\n\n#[test]\nfn packing_after_an_in_place_scan_reads_silu_not_samples() {\n    // the hazard the phase law exists for: interleaving pack+scan per tile\n    // corrupts tile n's history (tile n-1's rows are SiLU outputs by then)\n    let mut padded = Vec::new();\n    pack_padded(&mut padded);\n    let (ref_out, _) = scan_padded(&padded);\n\n    let w_t = w_tab();\n    let mut in_proj = [[0.0f32; C]; 128];\n    for token in 0..N {\n        for ch in 0..C {\n            in_proj[token][ch] = sample(token, ch);\n        }\n    }\n    let mut state_out = [[0.0f32; TAPS]; C];\n    scan_tiles_interleaved_wrong(&mut in_proj, &w_t, &mut state_out, N);\n    let mut diverged = 0;\n    for token in 0..N {\n        for ch in 0..C {\n            if in_proj[token][ch].to_bits() != ref_out[token][ch].to_bits() {\n                diverged += 1;\n            }\n        }\n    }\n    assert!(diverged > 0, \"the interleaved order must corrupt the in-place form\");\n}\n".to_string(),
        },
        // ── (gpu_105's two gates own the pass and the broadcast; this owns the
        // granularity axis itself.) ──
        // ── B: the hoist unit is the TERM's unit — a per-row scalar inside a
        // per-element visitor is re-derived per element; fill row_* register
        // arrays once per row slot (mask included) and index them. ──
        KernelRule {
            rule_id: "per-row-transcendental-hoist-not-per-element".to_string(),
            gpu_concept: "MECHANISM (per-row transcendental hoist; category B — compute): inside a fragment-parallel kernel, a lane's element visitor (map_coords) runs per (row, col) — any per-ROW term written INSIDE it is re-derived PER ELEMENT. The commit's own axis, verbatim: 'Scan: per-row `beta` / `exp(g)` / `exp(g_last - g)` computed once per row, not per element. 386 → 315 µs.' THE HOISTED FORM: the row terms fill register arrays once per row slot — the kernel's own law, verbatim (output_and_state.metal:77): '// Per-row terms are hoisted into row_* arrays: a lane owns rows lane_row + slot * ROW_STRIDE.' — declared 'float row_beta[TOKEN_ROW_SLOTS];' + 'float row_exp_g[TOKEN_ROW_SLOTS];' (output_and_state.metal:123-124) and filled with the validity mask riding the hoist (output_and_state.metal:162-163): 'row_beta[slot] = valid ? beta[token * num_v_heads + hv_idx] : 0.0f;' + 'row_exp_g[slot] = valid ? fast::exp(g_head[token]) : 0.0f;' — an invalid row never calls the transcendental. The element visitor then only INDEXES the arrays, verbatim (output_and_state.metal:173): 'return row_beta[row / ROW_STRIDE] * (value_input - row_exp_g[row / ROW_STRIDE] * state_projection);' against the removed per-element hunk that re-derived both terms inside map_coords ('const float beta_t = beta[token * num_v_heads + hv_idx];' + 'const float g_t = g_head[token];' + 'return beta_t * (value_input - fast::exp(g_t) * state_projection);'). THE CROSS-PHASE REUSE is the second half: row_exp_g is filled once in the R phase and the output phase consumes the same array ('return value * row_exp_g[row / ROW_STRIDE];'), and the decay face gets its own array per key tile — verbatim (output_and_state.metal:296-305): 'float row_decay[ROW_SLOTS];' + 'row_decay[slot] = row < valid_source_tokens ? fast::exp(g_last - g_head[token_base + source_token_block_start + row]) : 0.0f;' + the carried comment '// beta is already folded into Vnew through R.' + 'return value * row_decay[row / ROW_STRIDE];'. DECISION CONTENT: (a) the granularity axis — the loop-invariant term's unit is the ROW, the visitor's unit is the ELEMENT; hoist to the term's own unit, never wider; (b) bit-preservation is by construction: the same exp on the same argument bits, the same downstream expression order — the hoist is a pure motion, never a reassociation; (c) the validity mask rides the hoist (valid ? term : 0) so masked rows pay nothing; (d) the arrays are REGISTER arrays sized by the lane's row-slot count (TOKEN_ROW_SLOTS = TOKEN_FRAGMENTS * ROW_SLOTS) — not buffers, not a separate pass. CLASS SIGNATURE: a per-element visitor whose expression reads only the row index — the term is row-granular, the visitor element-granular. REGIME: fragment/simdgroup kernels where per-row scalars (gates, decays, per-row scales) sit inside element-wise lambdas over wide value dims. ANTI-REGIME: terms that genuinely vary per element (hoisting them changes the math); rows so short the array bookkeeping dominates; a separate precompute PASS shape when the in-kernel hoist is free. KINSHIP (do not double-count): gate-activation-precompute-pass-token-threshold-gated (gpu_105) owns the CROSS-WARP redundancy axis — N column-warps re-deriving one per-(token, head) gate — hoisted to a SEPARATE PRECOMPUTE PASS behind token thresholds (>= 32 / >= 64); THIS is the in-kernel granularity hoist inside ONE lane's own fragments, no pass, no threshold. verify-ubatch-full-prestage-lane-token-gate-broadcast (gpu_105) owns the distribute-BROADCAST form (each transcendental exactly once per BLOCK, lane t evaluates and __shfl_sync broadcasts at the 8-16 token band); THIS is the per-LANE register-array form — no broadcast, each lane hoists its own rows. NOVEL (grep 'row_beta|row_exp_g|g_last|once per row' over both corpora at claim): zero owners; the 'hoist' hits are CPU-domain rust_perf rules (regex-hoist-lazylock, dispatch-handler-pair-hoist, finder-hoist-reuse, mask-memo-hoist-to-owner-lifetime — owner-lifetime memos, not element-loop granularity) and kernel_opt rules hoisting WORK across kernels — no owner of per-row-vs-per-element. NotBenchable here (the 386 → 315 µs scan row is source-reported on M5 Max — different silicon, never our bench claim; the instruments are the bit pins). Source: trymirai/uzu @ e744e7cf4dc52e14f127d201aa04d24efb07a0c7 (MIT) — backends/metal/kernel/gdn/chunked/output_and_state.metal:77-124,155-173,296-305 at e744e7c. Batch 259 / Plan 263 / Research 295.".to_string(),
            ref_shape: "// naive: the R-phase residual, the O-phase output scale, and the key-decay\n// phase all sit INSIDE the element loop — every (row, col) fragment element\n// pays its row's transcendental again (the map_coords lambda re-derives\n// beta + exp(g) per element, the key phase re-derives exp(g_last - g) per\n// element). ROWS token rows x COLS value columns per row slice.\nconst ROWS: usize = 4; // token rows this lane's fragment spans\nconst COLS: usize = 4; // value columns per row slice\nconst KROWS: usize = 4; // key rows in the decay phase\n\nfn counted_exp(x: f32, calls: &mut usize) -> f32 {\n    *calls += 1;\n    x.exp()\n}\n\nfn g(row: usize) -> f32 {\n    -(((row * 3 + 1) as i32) * 25) as f32 / 100.0 // dyadic: -0.25, -1.0, -1.75, -2.5\n}\n\nfn beta(row: usize) -> f32 {\n    if row % 2 == 0 {\n        0.5\n    } else {\n        1.0\n    }\n}\n\nfn g_last() -> f32 {\n    -4.0\n}\n\nfn value(row: usize, col: usize) -> f32 {\n    (((row * 5 + col * 3) % 9) as i32 - 4) as f32\n}\n\nfn state(row: usize, col: usize) -> f32 {\n    (((row * 3 + col * 7) % 7) as i32 - 3) as f32\n}\n\n/// phase R: residual = beta * (v - exp(g) * state_projection) — per ELEMENT\nfn phase_r_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            let g_t = counted_exp(g(row), calls); // the ROW's exp, paid per element\n            out[row][col] = beta(row) * (value(row, col) - g_t * state(row, col));\n        }\n    }\n    out\n}\n\n/// phase O: the output value scaled by exp(g) — per ELEMENT again\nfn phase_o_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * counted_exp(g(row), calls);\n        }\n    }\n    out\n}\n\n/// the decay phase: exp(g_last - g[row]) per KEY element\nfn phase_k_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; KROWS] {\n    let mut out = [[0.0f32; COLS]; KROWS];\n    for row in 0..KROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * counted_exp(g_last() - g(row), calls);\n        }\n    }\n    out\n}\n\n#[test]\nfn the_naive_form_pays_exp_per_element() {\n    let mut calls = 0;\n    let _ = phase_r_naive(ROWS, &mut calls);\n    let _ = phase_o_naive(ROWS, &mut calls);\n    let _ = phase_k_naive(ROWS, &mut calls);\n    assert_eq!(calls, 2 * ROWS * COLS + KROWS * COLS, \"every element pays its row's exp\");\n}\n\n#[test]\nfn the_naive_masked_rows_still_skip_the_math() {\n    let mut full = 0;\n    let _ = phase_r_naive(ROWS, &mut full);\n    let _ = phase_o_naive(ROWS, &mut full);\n    let _ = phase_k_naive(ROWS, &mut full);\n    let mut masked = 0;\n    let _ = phase_r_naive(ROWS - 1, &mut masked);\n    let _ = phase_o_naive(ROWS - 1, &mut masked);\n    let _ = phase_k_naive(ROWS - 1, &mut masked);\n    assert_eq!(full - masked, 3 * COLS, \"an invalid row skips its COLS exp calls per phase\");\n}\n\n#[test]\nfn the_naive_outputs_are_the_baseline() {\n    let mut calls = 0;\n    let r = phase_r_naive(ROWS, &mut calls);\n    // spot-check: row 0, col 0 — beta 0.5, g -0.25\n    let e = (-0.25f32).exp();\n    assert_eq!(r[0][0].to_bits(), (0.5f32 * (value(0, 0) - e * state(0, 0))).to_bits());\n}\n".to_string(),
            opt_pattern: "// optimized: the per-row hoist — row_beta / row_exp_g / row_decay are\n// computed ONCE per row slot before the element loops (a lane owns rows\n// lane_row + slot * ROW_STRIDE), the element lambdas index the arrays, and\n// phase O reuses phase R's row_exp_g. Identical arithmetic on identical\n// bits: the outputs are bit-equal to the per-element form, the exp count\n// drops from per-element to per-row.\nconst ROWS: usize = 4;\nconst COLS: usize = 4;\nconst KROWS: usize = 4;\n\nfn counted_exp(x: f32, calls: &mut usize) -> f32 {\n    *calls += 1;\n    x.exp()\n}\n\nfn g(row: usize) -> f32 {\n    -(((row * 3 + 1) as i32) * 25) as f32 / 100.0\n}\n\nfn beta(row: usize) -> f32 {\n    if row % 2 == 0 {\n        0.5\n    } else {\n        1.0\n    }\n}\n\nfn g_last() -> f32 {\n    -4.0\n}\n\nfn value(row: usize, col: usize) -> f32 {\n    (((row * 5 + col * 3) % 9) as i32 - 4) as f32\n}\n\nfn state(row: usize, col: usize) -> f32 {\n    (((row * 3 + col * 7) % 7) as i32 - 3) as f32\n}\n\n// the ref_shape per-element form, re-declared so the bit-equality check\n// and the count reduction are local\nfn phase_r_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            let g_t = counted_exp(g(row), calls);\n            out[row][col] = beta(row) * (value(row, col) - g_t * state(row, col));\n        }\n    }\n    out\n}\n\nfn phase_o_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * counted_exp(g(row), calls);\n        }\n    }\n    out\n}\n\nfn phase_k_naive(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; KROWS] {\n    let mut out = [[0.0f32; COLS]; KROWS];\n    for row in 0..KROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * counted_exp(g_last() - g(row), calls);\n        }\n    }\n    out\n}\n\n/// the row hoist: one pass per row slot — valid ? term : 0, exactly the\n/// kernel's row_beta / row_exp_g fill\nfn hoist_rows(valid_rows: usize, calls: &mut usize) -> ([f32; ROWS], [f32; ROWS]) {\n    let mut row_beta = [0.0f32; ROWS];\n    let mut row_exp_g = [0.0f32; ROWS];\n    for row in 0..ROWS {\n        if row < valid_rows {\n            row_beta[row] = beta(row);\n            row_exp_g[row] = counted_exp(g(row), calls);\n        }\n    }\n    (row_beta, row_exp_g)\n}\n\nfn phase_r_opt(valid_rows: usize, row_beta: &[f32; ROWS], row_exp_g: &[f32; ROWS]) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = row_beta[row] * (value(row, col) - row_exp_g[row] * state(row, col));\n        }\n    }\n    out\n}\n\nfn phase_o_opt(valid_rows: usize, row_exp_g: &[f32; ROWS]) -> [[f32; COLS]; ROWS] {\n    let mut out = [[0.0f32; COLS]; ROWS];\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * row_exp_g[row]; // reused from phase R\n        }\n    }\n    out\n}\n\n/// the decay hoist: row_decay once per key tile, consumed per element\nfn phase_k_opt(valid_rows: usize, calls: &mut usize) -> [[f32; COLS]; KROWS] {\n    let mut row_decay = [0.0f32; KROWS];\n    for row in 0..KROWS {\n        if row < valid_rows {\n            row_decay[row] = counted_exp(g_last() - g(row), calls);\n        }\n    }\n    let mut out = [[0.0f32; COLS]; KROWS];\n    for row in 0..KROWS {\n        for col in 0..COLS {\n            if row >= valid_rows {\n                out[row][col] = 0.0;\n                continue;\n            }\n            out[row][col] = value(row, col) * row_decay[row];\n        }\n    }\n    out\n}\n\n#[test]\nfn the_hoist_reproduces_the_per_element_bits() {\n    let mut calls = 0;\n    let (rb, rg) = hoist_rows(ROWS, &mut calls);\n    let r = phase_r_opt(ROWS, &rb, &rg);\n    let o = phase_o_opt(ROWS, &rg);\n    let mut ref_calls = 0;\n    let r_ref = phase_r_naive(ROWS, &mut ref_calls);\n    let o_ref = phase_o_naive(ROWS, &mut ref_calls);\n    for row in 0..ROWS {\n        for col in 0..COLS {\n            assert_eq!(r[row][col].to_bits(), r_ref[row][col].to_bits(), \"R phase row {row} col {col}\");\n            assert_eq!(o[row][col].to_bits(), o_ref[row][col].to_bits(), \"O phase row {row} col {col}\");\n        }\n    }\n}\n\n#[test]\nfn the_exp_count_drops_from_per_element_to_per_row() {\n    let mut calls = 0;\n    let _ = hoist_rows(ROWS, &mut calls);\n    let _ = phase_r_opt(ROWS, &[0.5, 1.0, 0.5, 1.0], &[0.1; ROWS]);\n    let _ = phase_o_opt(ROWS, &[0.1; ROWS]);\n    let _ = phase_k_opt(ROWS, &mut calls);\n    assert_eq!(calls, ROWS + KROWS, \"one exp per row slot, phases share row_exp_g\");\n    let mut ref_calls = 0;\n    let _ = phase_r_naive(ROWS, &mut ref_calls);\n    let _ = phase_o_naive(ROWS, &mut ref_calls);\n    let _ = phase_k_naive(ROWS, &mut ref_calls);\n    assert_eq!(ref_calls, 2 * ROWS * COLS + KROWS * COLS);\n    // combined reduction: R+O share one hoist, decay hoists its own —\n    // C*(2R+K)/(R+K) = 6 here, never below the row's column width\n    assert_eq!(ref_calls / calls, COLS * (2 * ROWS + KROWS) / (ROWS + KROWS));\n}\n\n#[test]\nfn invalid_rows_pay_no_exp_in_the_hoist_either() {\n    let mut full = 0;\n    let _ = hoist_rows(ROWS, &mut full);\n    let _ = phase_k_opt(ROWS, &mut full);\n    let mut masked = 0;\n    let _ = hoist_rows(ROWS - 1, &mut masked);\n    let _ = phase_k_opt(ROWS - 1, &mut masked);\n    assert_eq!(full - masked, 2, \"one R/O exp + one decay exp skipped for the masked row\");\n    // and the masked row's outputs stay exactly zero in both phases\n    let (rb, rg) = hoist_rows(ROWS - 1, &mut masked);\n    let r = phase_r_opt(ROWS, &rb, &rg);\n    let o = phase_o_opt(ROWS, &rg);\n    assert_eq!(r[ROWS - 1], [0.0; COLS]);\n    assert_eq!(o[ROWS - 1], [0.0; COLS]);\n}\n\n#[test]\nfn the_decay_face_is_its_own_hoist() {\n    let mut calls = 0;\n    let k = phase_k_opt(KROWS, &mut calls);\n    let mut ref_calls = 0;\n    let k_ref = phase_k_naive(KROWS, &mut ref_calls);\n    for row in 0..KROWS {\n        for col in 0..COLS {\n            assert_eq!(k[row][col].to_bits(), k_ref[row][col].to_bits(), \"decay row {row} col {col}\");\n        }\n    }\n    assert_eq!(calls, KROWS);\n}\n".to_string(),
        },
        // ── C: the WY-precompute chain in ONE kernel — 6 -> 3 dispatches and
        // the hand-off scratch (kk / a_packed / a_inv) deleted from the
        // module: A lives in packed threadgroup tiles, the solve in register
        // blocks, and admission refuses wide groups to the recurrent path. ──
        KernelRule {
            rule_id: "precompute-chain-fused-intermediates-never-materialized".to_string(),
            gpu_concept: "MECHANISM (precompute-chain fusion, intermediates never born; category C — fusion): the WY-precompute chain of the chunked DeltaNet prefill collapses from four kernels into ONE — the new kernel's own header is the chain, verbatim (precompute.metal:26-30): '// One threadgroup owns one (chunk, k-head); simdgroup b owns block row b. Per grouped v-head:' + '// 1. g = prefix sum of log_decay.' + '// 2. qk_scaled = exp(g_r - g_c) * Q K^T for c <= r.' + '// 3. A = beta_r * exp(g_r - g_c) * K K^T for c < r.' + '// 4. T = (I + A)^-1 by block forward substitution.' — cumsum, gram, a_diag_inv and causal_inv all died (their .metal files are deleted at the pin), the full encode drops 6 -> 3 dispatches (prep + 4 + output_and_state -> prep + 1 + output_and_state; commit: 'Precompute: one kernel replaces cumsum / gram / a_diag_inv / causal_inv, 6 → 3 dispatches. 101 → 78 µs.'), and the hand-off GLOBAL scratch buffers are DELETED FROM mod.rs — not written-then-torn: the allocations no longer exist. The removed hunks: 'let mut kk = command_buffer' + '.allocate_scratch_for_shape(&[num_chunks, args.num_groups, CHUNK_SIZE, CHUNK_SIZE], INNER_DATA_TYPE)?;' + a_packed '[num_chunks, args.num_heads, num_blocks, num_col_pairs, BLOCK_SIZE, 2 * BLOCK_SIZE]' + a_inv '[num_chunks, args.num_heads, num_blocks, BLOCK_SIZE, BLOCK_SIZE]'. WHERE THE INTERMEDIATES LIVE NOW: A stays in threadgroup tiles with the strictly-lower block structure packed — verbatim (precompute.metal:72-73): '// First A tile of block row b in threadgroup memory: rows hold b / 2 + 1 tiles.' + 'auto tile_base = [](uint b) UZU_ALWAYS_INLINE { return b < 2 ? b : 2 * b - 2; };' — declared 'threadgroup float a_tiles[A_TILE_COUNT * BLOCK_SIZE * COL_TILE],' + 'threadgroup float diag_inverses[MAX_BLOCKS * BLOCK_SIZE * BLOCK_SIZE],' + the per-group decay staging 'threadgroup float g_tiles[MAX_GROUPS * CHUNK_SIZE],' + 'threadgroup float beta_tiles[MAX_GROUPS * CHUNK_SIZE],' (precompute.metal:46-49); the cumsum itself becomes a simd prefix scan inside the same kernel, verbatim (precompute.metal:142): 'const float prefix = carry + simd_prefix_inclusive_sum(decay_values[pass]);'; and the solve carries its results in registers, verbatim (precompute.metal:213+216): '// Solve this simdgroup's 16-column slice of T; blocks above the slice are zero, solved blocks stay in registers.' + 'ValueFragment t_blocks[num_blocks];'. THE ENABLER: the triangular-inverse helper gained a stride + generic destination so it reads strided threadgroup tiles and serves the fused layout without its own global round-trip, verbatim (tri_inv.h:8+30): 'template <uint BLOCK, uint A_STRIDE = BLOCK, typename OutPtr>' + 'acc += a_tile[row * A_STRIDE + prev_row] * inverse_col[prev_row];'. THE ADMISSION is dispatch-level and refuses BEFORE any encode: verbatim (chunked/mod.rs:47-50): '// The precompute kernel assigns one grouped v-head to each of its four simdgroups.' + 'if groups_per_head > 4 {' + 'return Ok(None);' — Ok(None) hands the layer to the recurrent path (MAX_GROUPS 4u is the same constant that sizes g_tiles/beta_tiles); the f16 outer-type gate rides the same constructor ('if outer_data_type == DataType::F16 {' -> Ok(None), conv side pins kernel_size == 4 as a constexpr variant — the commit's own limits line, verbatim: 'Limits: M5 only; `kernel_size` must be 4; heads per group > 4 falls back to recurrent.' Bit-equality fused-vs-chain is by construction (the same entry expressions in the same order); the shipped instrument is the chunked-vs-recurrent parity fixture, verbatim (chunked_test.rs:49+162-163): '/// `None` runs the recurrent kernels. The output is NaN-filled first so unwritten elements fail the comparison.' + 'is_close::default().abs_tol(5e-3).rel_tol(1e-3).all_close(chunked_out, recurrent_out)'. DECISION CONTENT: (a) the dispatch face — 6 -> 3 for the whole encode; (b) the allocation face — kk/a_packed/a_inv never materialize (deleted from the module); (c) the threadgroup-residency face — the a_tiles triangular packing (block row b holds b/2 + 1 column tiles: the strictly-lower structure IS the layout); (d) the register face — solved T blocks ride t_blocks across the substitution; (e) admission — groups_per_head > 4 -> Ok(None) recurrent fallback, f16 outer gate; (f) simdgroup-parallel decomposition — one threadgroup per (chunk, k-head), one simdgroup per block row. CLASS SIGNATURE: a stage graph whose edges are full matrices — fuse when every edge fits threadgroup scratch and the stages share ONE threadgroup-level decomposition. REGIME: chunked linear-attention prefill precompute chains (WY-rep class); per-chunk chains of small matrix ops with a per-(chunk, head) threadgroup owner. ANTI-REGIME: stages needing grid-wide sync between them; intermediates with a SECOND consumer kernel (the buffer cannot be deleted); shapes violating the admission ladder (wide groups -> the recurrent path). KINSHIP (do not double-count): register-resident-scan-state-one-kernel-layer-pass (gpu_93) owns the SCAN-STATE residency axis — the recurrent S never round-trips global within its one-kernel layer pass; THIS owns the PRECOMPUTE-INTERMEDIATES-never-born face PLUS the dispatch-count collapse — the same never-materialize discipline over a different resident (chain edges, not the scan state). in-register-unit-triangular-inverse-warp-substitution (gpu_93) owns the CUDA solve form (one row per warp, shuffle-broadcast pivots); the Metal sibling here is tri_inv.h's block substitution INSIDE the fused kernel — cite, not substitute. lifecycle-disjoint-intermediates-union-smem-scratch (gpu_94) owns smem-slot SHARING for two intermediates INSIDE one kernel (union, max-not-sum); THIS deletes cross-kernel GLOBAL intermediates outright. fusion-scope-by-barrier-cost-not-dispatch-count (gpu_85) owns the ADMISSION-AXIS law — the dispatch count is the proxy, the measured boundary cost the axis; HERE the two coincide honestly and both are priced: the fused kernel's added syncs are threadgroup-level (simdgroup_barrier + threadgroup_barrier per group) while the chain it replaced paid four dispatch boundaries AND three global-buffer round-trips, and the win is source-reported E2E (the commit's own row: 'prefill −2.6 % @30k, −3.5 % @102k' on M5 Max), never a dispatch-count argument alone. fused-moe-routing-prologue (gpu_20, same repo) owns dispatch-count fusion of a PRODUCING chain at decode scale in ONE threadgroup (histogram + scan + offsets, threadgroup atomics) — THIS is the prefill-scale MATRIX-chain sibling: one threadgroup per (chunk, k-head), simdgroup-parallel, with the deleted-global-scratch face gpu_20 does not own. cumsum-gate-to-decay-matrix / reverse-running-decay-weight (gpu_02) own the decay-math materialization alternatives (dematerialize the pairwise weights for a streaming consumer) — the cumsum here is staged in simd registers and written once as an OUTPUT. NOVEL (grep 'precompute chain|one kernel replaces|cumsum|a_diag_inv|causal_inv|block forward substitution|never born|intermediates never' over both corpora at claim): zero owners of the chain fusion with never-born intermediates — the cumsum hits route to the decay-math family and the MoE prologue, the never-materialize hit routes to gpu_93's scan-state residency. NotBenchable here (M5-only limits + source-reported numbers; the instruments are the chunked-vs-recurrent parity fixtures and the deleted-buffer shapes). Source: trymirai/uzu @ e744e7cf4dc52e14f127d201aa04d24efb07a0c7 (MIT) — backends/metal/kernel/gdn/chunked/precompute.metal:26-30,46-49,72-73,142,213-216, chunked/mod.rs:39-50, common/tri_inv.h:8-30, unit/backends/metal/kernel/gdn/chunked_test.rs:49,162-167 at e744e7c. Batch 259 / Plan 263 / Research 295.".to_string(),
            ref_shape: "// naive: the four-kernel precompute chain — cumsum, gram, a_diag_inv,\n// causal_inv each take a dispatch and each hand-off matrix is a GLOBAL\n// scratch buffer (kk, a_packed, a_inv born and torn per prefill). The full\n// encode is prep + 4 + output_and_state = 6 dispatches. Integer q/k rows\n// and dyadic decay keep the dots exact; exp(g_r - g_c) is the only\n// transcendental and both forms call it with identical bits.\nconst CHUNK: usize = 8;\nconst BLOCK: usize = 4;\nconst NB: usize = 2; // CHUNK / BLOCK\nconst KD: usize = 4; // key_dim\nconst VH: usize = 2; // num_v_heads\nconst KH: usize = 1; // num_k_heads\nconst SUFFIX: usize = 13; // chunk 0 full, chunk 1 partial (5 valid tokens)\nconst NCHUNK: usize = 2;\n\nfn prefix(seq: &[f32]) -> Vec<f32> {\n    let mut out = Vec::with_capacity(seq.len());\n    let mut run = 0.0f32;\n    for &x in seq {\n        run += x;\n        out.push(run);\n    }\n    out\n}\n\nfn g_at(chunk: usize, head: usize, row: usize, g: &[Vec<f32>]) -> f32 {\n    g[chunk * VH + head][row]\n}\n\nfn beta_at(chunk: usize, head: usize, row: usize, beta: &[f32]) -> f32 {\n    beta[(chunk * CHUNK + row) * VH + head]\n}\n\n/// beta_r * exp(g_r - g_c) * kk_rc — the kernel's map_coords expression,\n/// left-associated exactly as written\nfn a_entry(beta_r: f32, g_r: f32, g_c: f32, kk_rc: f32) -> f32 {\n    beta_r * (g_r - g_c).exp() * kk_rc\n}\n\n/// qk_rc * exp(g_r - g_c) — the decay-scaled causal Q K^T entry\nfn qk_entry(qk_rc: f32, g_r: f32, g_c: f32) -> f32 {\n    qk_rc * (g_r - g_c).exp()\n}\n\n/// (I + strictly-lower m)^-1, column-wise forward substitution — the\n/// tri_inv.h loop: x[col] = 1, x[row] = -(m[row][col] + sum m[row][prev] x[prev])\nfn unit_lower_inverse(m: &[[f32; BLOCK]; BLOCK]) -> [[f32; BLOCK]; BLOCK] {\n    let mut inv = [[0.0f32; BLOCK]; BLOCK];\n    for col in 0..BLOCK {\n        inv[col][col] = 1.0;\n        for row in col + 1..BLOCK {\n            let mut acc = m[row][col];\n            for prev in col + 1..row {\n                acc += m[row][prev] * inv[prev][col];\n            }\n            inv[row][col] = -acc;\n        }\n    }\n    inv\n}\n\n/// the causal_inv composition: T_b = Dinv_b @ (I_b - sum_{j<b} A[b][j] @ T_j),\n/// the block forward substitution with the solved blocks carried along\nfn compose_block(b: usize, a: &[[f32; CHUNK]; CHUNK], dinv: &[[f32; BLOCK]; BLOCK], t_blocks: &[[[f32; CHUNK]; BLOCK]; NB]) -> [[f32; CHUNK]; BLOCK] {\n    let mut acc = [[0.0f32; CHUNK]; BLOCK];\n    for i in 0..BLOCK {\n        acc[i][b * BLOCK + i] = 1.0;\n    }\n    for j in 0..b {\n        for i in 0..BLOCK {\n            for col in 0..BLOCK {\n                let mut s = 0.0f32;\n                for p in 0..BLOCK {\n                    s += a[b * BLOCK + i][j * BLOCK + p] * t_blocks[j][p][j * BLOCK + col];\n                }\n                acc[i][j * BLOCK + col] -= s;\n            }\n        }\n    }\n    let mut out = [[0.0f32; CHUNK]; BLOCK];\n    for i in 0..BLOCK {\n        for col in 0..CHUNK {\n            let mut s = 0.0f32;\n            for p in 0..BLOCK {\n                s += dinv[i][p] * acc[p][col];\n            }\n            out[i][col] = s;\n        }\n    }\n    out\n}\n\n// deterministic inputs: integer q/k rows, dyadic decay + beta\nfn q_at(token: usize, d: usize) -> f32 {\n    ((token * 3 + d * 5) % 7) as i32 as f32 - 3.0\n}\n\nfn k_at(token: usize, d: usize) -> f32 {\n    ((token * 5 + d * 3) % 5) as i32 as f32 - 2.0\n}\n\nfn log_decay_at(token: usize, head: usize) -> f32 {\n    -(((token * 2 + head * 3) % 4 + 1) as f32) * 0.25\n}\n\nfn beta_input(token: usize, head: usize) -> f32 {\n    if (token + head) % 2 == 0 {\n        0.5\n    } else {\n        1.0\n    }\n}\n\nstruct Counters {\n    dispatches: Vec<&'static str>,\n    intermediate_allocs: usize,\n    intermediate_touches: usize,\n}\n\n/// the full naive encode: prep, cumsum, gram, a_diag_inv, causal_inv,\n/// output_and_state — 6 dispatches, 3 intermediate global buffers\nfn encode_naive() -> (Vec<Vec<f32>>, Vec<Vec<f32>>, Vec<f32>, Counters) {\n    let mut c = Counters {\n        dispatches: Vec::new(),\n        intermediate_allocs: 0,\n        intermediate_touches: 0,\n    };\n    // -- prep: q_norm / k_norm / log_decay / beta materialize\n    c.dispatches.push(\"prep\");\n    // -- cumsum: g[chunk][head] = prefix(log_decay) — a global scratch\n    c.dispatches.push(\"cumsum\");\n    let mut g: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let seq: Vec<f32> = (0..valid).map(|r| log_decay_at(base + r, head)).collect();\n            g.push(prefix(&seq));\n        }\n    }\n    // -- gram: decay-scaled causal Q K^T (an output) + raw K K^T (an\n    //    intermediate: kk, [NCHUNK][KH][CHUNK][CHUNK])\n    c.dispatches.push(\"gram\");\n    c.intermediate_allocs += 1;\n    let mut kk = vec![[[0.0f32; CHUNK]; CHUNK]; NCHUNK * KH];\n    let mut qk: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc <= r {\n                        let mut raw = 0.0f32;\n                        for d in 0..KD {\n                            raw += q_at(base + r, d) * k_at(base + cc, d);\n                        }\n                        tile[r][cc] = qk_entry(raw, g_at(chunk, head, r, &g), g_at(chunk, head, cc, &g));\n                    }\n                }\n            }\n            qk.push(tile.iter().flatten().copied().collect::<Vec<f32>>());\n        }\n        for h in 0..KH {\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc < r {\n                        let mut raw = 0.0f32;\n                        for d in 0..KD {\n                            raw += k_at(base + r, d) * k_at(base + cc, d);\n                        }\n                        tile[r][cc] = raw;\n                    }\n                }\n            }\n            kk[chunk * KH + h] = tile;\n            c.intermediate_touches += CHUNK * CHUNK;\n        }\n    }\n    // -- a_diag_inv: A = beta*exp(g_r-g_c)*kk -> a_packed + per-block\n    //    diagonal inverses (two more intermediates)\n    c.dispatches.push(\"a_diag_inv\");\n    c.intermediate_allocs += 2;\n    let beta_all = beta_input_all();\n    let mut a_packed = vec![[[0.0f32; CHUNK]; CHUNK]; NCHUNK * VH];\n    let mut a_inv = vec![[[[0.0f32; BLOCK]; BLOCK]; NB]; NCHUNK * VH];\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc < r {\n                        tile[r][cc] = a_entry(\n                            beta_at(chunk, head, r, &beta_all),\n                            g_at(chunk, head, r, &g),\n                            g_at(chunk, head, cc, &g),\n                            kk[chunk * KH][r][cc],\n                        );\n                    }\n                }\n            }\n            a_packed[chunk * VH + head] = tile;\n            c.intermediate_touches += CHUNK * CHUNK;\n            for b in 0..NB {\n                let mut diag = [[0.0f32; BLOCK]; BLOCK];\n                for i in 0..BLOCK {\n                    for j in 0..BLOCK {\n                        diag[i][j] = tile[b * BLOCK + i][b * BLOCK + j];\n                    }\n                }\n                a_inv[chunk * VH + head][b] = unit_lower_inverse(&diag);\n                c.intermediate_touches += BLOCK * BLOCK;\n            }\n        }\n    }\n    // -- causal_inv: T = (I+A)^-1 from a_packed + a_inv (reads both back)\n    c.dispatches.push(\"causal_inv\");\n    let mut t: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        for head in 0..VH {\n            let a = &a_packed[chunk * VH + head];\n            let mut t_blocks = [[[0.0f32; CHUNK]; BLOCK]; NB];\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for b in 0..NB {\n                t_blocks[b] = compose_block(b, a, &a_inv[chunk * VH + head][b], &t_blocks);\n                for i in 0..BLOCK {\n                    for col in 0..CHUNK {\n                        tile[b * BLOCK + i][col] = t_blocks[b][i][col];\n                    }\n                }\n            }\n            c.intermediate_touches += CHUNK * CHUNK * 2; // a_packed + a_inv read back\n            t.push(tile.iter().flatten().copied().collect::<Vec<f32>>());\n        }\n    }\n    // -- output_and_state consumes qk + t\n    c.dispatches.push(\"output_and_state\");\n    (qk, t, g.concat(), c)\n}\n\nfn beta_input_all() -> Vec<f32> {\n    let mut b = vec![0.0f32; SUFFIX * VH];\n    for token in 0..SUFFIX {\n        for head in 0..VH {\n            b[token * VH + head] = beta_input(token, head);\n        }\n    }\n    b\n}\n\n#[test]\nfn the_chain_costs_four_dispatches_and_three_intermediates() {\n    let (_, _, _, c) = encode_naive();\n    assert_eq!(c.dispatches, vec![\"prep\", \"cumsum\", \"gram\", \"a_diag_inv\", \"causal_inv\", \"output_and_state\"]);\n    assert_eq!(c.dispatches.len(), 6, \"prep + 4 + output_and_state\");\n    assert_eq!(c.intermediate_allocs, 3, \"kk + a_packed + a_inv born as global scratch\");\n    assert!(c.intermediate_touches > 0, \"every intermediate is written and read back\");\n}\n\n#[test]\nfn the_naive_t_is_the_unit_lower_inverse() {\n    let (_qk, t, _g, _c) = encode_naive();\n    // chunk 0, head 0: T must be unit lower with (I+A)@T ~= I\n    let tile: [[f32; CHUNK]; CHUNK] = t[0].chunks_exact(CHUNK).map(|r| r.try_into().unwrap()).collect::<Vec<_>>().try_into().unwrap();\n    assert_eq!(tile[0][0], 1.0);\n    for r in 0..CHUNK {\n        for cc in (r + 1)..CHUNK {\n            assert_eq!(tile[r][cc], 0.0, \"upper triangle stays zero at {r},{cc}\");\n        }\n    }\n    // rebuild A and check the inverse residual within exp noise\n    let mut a = [[0.0f32; CHUNK]; CHUNK];\n    let g0 = prefix(&(0..CHUNK).map(|r| log_decay_at(r, 0)).collect::<Vec<_>>());\n    for r in 0..CHUNK {\n        for cc in 0..r {\n            let mut raw = 0.0f32;\n            for d in 0..KD {\n                raw += k_at(r, d) * k_at(cc, d);\n            }\n            a[r][cc] = a_entry(beta_input(r, 0), g0[r], g0[cc], raw);\n        }\n    }\n    for i in 0..CHUNK {\n        for j in 0..CHUNK {\n            let mut s = 0.0f32;\n            for p in 0..CHUNK {\n                let ia = if i == p { 1.0 } else { 0.0 } + if p > i { 0.0 } else { 0.0 };\n                let _ = ia;\n                s += (if i == p { 1.0 } else { 0.0 } + a[i][p]) * tile[p][j];\n            }\n            let want = if i == j { 1.0 } else { 0.0 };\n            assert!((s - want).abs() < 1e-3, \"inverse residual at {i},{j}: {s}\");\n        }\n    }\n}\n".to_string(),
            opt_pattern: "// optimized: DeltaNetChunkedPrecompute — ONE kernel runs the whole chain\n// (prefix-sum decay, decay-scaled Q K^T, beta*exp-scaled K K^T, per-block\n// diagonal inverses, block forward substitution to T). The hand-off\n// matrices (kk, a_packed, a_inv) are never born: A and the inverses live\n// in threadgroup tiles, the solved T blocks stay in the register array,\n// and only the outputs (g, qk_scaled, t) are written. The full encode is\n// prep + precompute + output_and_state = 3 dispatches. Admission: f16\n// outer type refuses; groups_per_head > 4 refuses (one grouped v-head per\n// simdgroup) and the caller falls back to the recurrent path.\nconst CHUNK: usize = 8;\nconst BLOCK: usize = 4;\nconst NB: usize = 2;\nconst KD: usize = 4;\nconst VH: usize = 2;\nconst KH: usize = 1;\nconst SUFFIX: usize = 13;\nconst NCHUNK: usize = 2;\nconst MAX_GROUPS: usize = 4; // #define MAX_GROUPS 4u — g_tiles/beta_tiles sizing\n\n#[derive(Clone, Copy, PartialEq)]\nenum Outer {\n    Bf16,\n    F16,\n    F32,\n}\n\n/// the host admission: f16 outer-type gate + the groups_per_head gate;\n/// Ok(None) hands the layer back to the recurrent kernels\nfn admit(groups_per_head: usize, outer: Outer) -> Option<&'static str> {\n    if outer == Outer::F16 {\n        return None;\n    }\n    // The precompute kernel assigns one grouped v-head to each of its four\n    // simdgroups — a fifth group has no simdgroup to live in.\n    if groups_per_head > MAX_GROUPS {\n        return None;\n    }\n    Some(\"chunked_precompute\")\n}\n\nfn prefix(seq: &[f32]) -> Vec<f32> {\n    let mut out = Vec::with_capacity(seq.len());\n    let mut run = 0.0f32;\n    for &x in seq {\n        run += x;\n        out.push(run);\n    }\n    out\n}\n\nfn g_at(chunk: usize, head: usize, row: usize, g: &[Vec<f32>]) -> f32 {\n    g[chunk * VH + head][row]\n}\n\nfn beta_at(chunk: usize, head: usize, row: usize, beta: &[f32]) -> f32 {\n    beta[(chunk * CHUNK + row) * VH + head]\n}\n\nfn a_entry(beta_r: f32, g_r: f32, g_c: f32, kk_rc: f32) -> f32 {\n    beta_r * (g_r - g_c).exp() * kk_rc\n}\n\nfn qk_entry(qk_rc: f32, g_r: f32, g_c: f32) -> f32 {\n    qk_rc * (g_r - g_c).exp()\n}\n\nfn unit_lower_inverse(m: &[[f32; BLOCK]; BLOCK]) -> [[f32; BLOCK]; BLOCK] {\n    let mut inv = [[0.0f32; BLOCK]; BLOCK];\n    for col in 0..BLOCK {\n        inv[col][col] = 1.0;\n        for row in col + 1..BLOCK {\n            let mut acc = m[row][col];\n            for prev in col + 1..row {\n                acc += m[row][prev] * inv[prev][col];\n            }\n            inv[row][col] = -acc;\n        }\n    }\n    inv\n}\n\nfn compose_block(b: usize, a: &[[f32; CHUNK]; CHUNK], dinv: &[[f32; BLOCK]; BLOCK], t_blocks: &[[[f32; CHUNK]; BLOCK]; NB]) -> [[f32; CHUNK]; BLOCK] {\n    let mut acc = [[0.0f32; CHUNK]; BLOCK];\n    for i in 0..BLOCK {\n        acc[i][b * BLOCK + i] = 1.0;\n    }\n    for j in 0..b {\n        for i in 0..BLOCK {\n            for col in 0..BLOCK {\n                let mut s = 0.0f32;\n                for p in 0..BLOCK {\n                    s += a[b * BLOCK + i][j * BLOCK + p] * t_blocks[j][p][j * BLOCK + col];\n                }\n                acc[i][j * BLOCK + col] -= s;\n            }\n        }\n    }\n    let mut out = [[0.0f32; CHUNK]; BLOCK];\n    for i in 0..BLOCK {\n        for col in 0..CHUNK {\n            let mut s = 0.0f32;\n            for p in 0..BLOCK {\n                s += dinv[i][p] * acc[p][col];\n            }\n            out[i][col] = s;\n        }\n    }\n    out\n}\n\nfn q_at(token: usize, d: usize) -> f32 {\n    ((token * 3 + d * 5) % 7) as i32 as f32 - 3.0\n}\n\nfn k_at(token: usize, d: usize) -> f32 {\n    ((token * 5 + d * 3) % 5) as i32 as f32 - 2.0\n}\n\nfn log_decay_at(token: usize, head: usize) -> f32 {\n    -(((token * 2 + head * 3) % 4 + 1) as f32) * 0.25\n}\n\nfn beta_input(token: usize, head: usize) -> f32 {\n    if (token + head) % 2 == 0 {\n        0.5\n    } else {\n        1.0\n    }\n}\n\nfn beta_input_all() -> Vec<f32> {\n    let mut b = vec![0.0f32; SUFFIX * VH];\n    for token in 0..SUFFIX {\n        for head in 0..VH {\n            b[token * VH + head] = beta_input(token, head);\n        }\n    }\n    b\n}\n\nstruct Counters {\n    dispatches: Vec<&'static str>,\n    intermediate_allocs: usize,\n    intermediate_touches: usize,\n}\n\n/// the fused encode: prep, precompute, output_and_state — 3 dispatches,\n/// zero intermediate buffers (kk / a_packed / a_inv are never allocated)\nfn encode_fused() -> (Vec<Vec<f32>>, Vec<Vec<f32>>, Vec<f32>, Counters) {\n    let mut c = Counters {\n        dispatches: Vec::new(),\n        intermediate_allocs: 0,\n        intermediate_touches: 0,\n    };\n    c.dispatches.push(\"prep\");\n    let beta_all = beta_input_all();\n    c.dispatches.push(\"precompute\");\n    let mut g: Vec<Vec<f32>> = Vec::new();\n    let mut qk: Vec<Vec<f32>> = Vec::new();\n    let mut t: Vec<Vec<f32>> = Vec::new();\n    // one threadgroup per (chunk, k-head); the g tiles ride the local\n    // scratch (g_tiles[MAX_GROUPS * CHUNK_SIZE]) exactly as the kernel's\n    // simdgroup b stages grouped v-head b\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        let mut g_tiles = vec![vec![0.0f32; CHUNK]; VH];\n        for head in 0..VH {\n            let seq: Vec<f32> = (0..valid).map(|r| log_decay_at(base + r, head)).collect();\n            g_tiles[head] = prefix(&seq);\n            g.push(g_tiles[head].clone());\n        }\n        for head in 0..VH {\n            // the Gram accumulators and the A tile live in threadgroup\n            // scratch (a_tiles), never in a global buffer\n            let mut qk_tile = [[0.0f32; CHUNK]; CHUNK];\n            let mut a_tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc <= r {\n                        let mut q_raw = 0.0f32;\n                        for d in 0..KD {\n                            q_raw += q_at(base + r, d) * k_at(base + cc, d);\n                        }\n                        qk_tile[r][cc] = qk_entry(q_raw, g_tiles[head][r], g_tiles[head][cc]);\n                    }\n                    if cc < r {\n                        let mut kk_raw = 0.0f32;\n                        for d in 0..KD {\n                            kk_raw += k_at(base + r, d) * k_at(base + cc, d);\n                        }\n                        a_tile[r][cc] = a_entry(\n                            beta_at(chunk, head, r, &beta_all),\n                            g_tiles[head][r],\n                            g_tiles[head][cc],\n                            kk_raw,\n                        );\n                    }\n                }\n            }\n            qk.push(qk_tile.iter().flatten().copied().collect::<Vec<f32>>());\n            // the diagonal inverses stay in the local scratch\n            // (diag_inverses[MAX_BLOCKS * BLOCK * BLOCK]); the solved T\n            // blocks stay in the register array t_blocks\n            let mut dinv = [[[0.0f32; BLOCK]; BLOCK]; NB];\n            for b in 0..NB {\n                let mut diag = [[0.0f32; BLOCK]; BLOCK];\n                for i in 0..BLOCK {\n                    for j in 0..BLOCK {\n                        diag[i][j] = a_tile[b * BLOCK + i][b * BLOCK + j];\n                    }\n                }\n                dinv[b] = unit_lower_inverse(&diag);\n            }\n            let mut t_blocks = [[[0.0f32; CHUNK]; BLOCK]; NB];\n            let mut t_tile = [[0.0f32; CHUNK]; CHUNK];\n            for b in 0..NB {\n                t_blocks[b] = compose_block(b, &a_tile, &dinv[b], &t_blocks);\n                for i in 0..BLOCK {\n                    for col in 0..CHUNK {\n                        t_tile[b * BLOCK + i][col] = t_blocks[b][i][col];\n                    }\n                }\n            }\n            t.push(t_tile.iter().flatten().copied().collect::<Vec<f32>>());\n        }\n    }\n    c.dispatches.push(\"output_and_state\");\n    (qk, t, g.concat(), c)\n}\n\n// the ref_shape four-kernel chain, re-declared so the bit-equality and\n// dispatch-count checks are local\nfn encode_naive() -> (Vec<Vec<f32>>, Vec<Vec<f32>>, Vec<f32>, Counters) {\n    let mut c = Counters {\n        dispatches: Vec::new(),\n        intermediate_allocs: 0,\n        intermediate_touches: 0,\n    };\n    c.dispatches.push(\"prep\");\n    c.dispatches.push(\"cumsum\");\n    let mut g: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let seq: Vec<f32> = (0..valid).map(|r| log_decay_at(base + r, head)).collect();\n            g.push(prefix(&seq));\n        }\n    }\n    c.dispatches.push(\"gram\");\n    c.intermediate_allocs += 1;\n    let mut kk = vec![[[0.0f32; CHUNK]; CHUNK]; NCHUNK * KH];\n    let mut qk: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc <= r {\n                        let mut raw = 0.0f32;\n                        for d in 0..KD {\n                            raw += q_at(base + r, d) * k_at(base + cc, d);\n                        }\n                        tile[r][cc] = qk_entry(raw, g_at(chunk, head, r, &g), g_at(chunk, head, cc, &g));\n                    }\n                }\n            }\n            qk.push(tile.iter().flatten().copied().collect::<Vec<f32>>());\n        }\n        let mut ktile = [[0.0f32; CHUNK]; CHUNK];\n        for r in 0..valid {\n            for cc in 0..valid {\n                if cc < r {\n                    let mut raw = 0.0f32;\n                    for d in 0..KD {\n                        raw += k_at(base + r, d) * k_at(base + cc, d);\n                    }\n                    ktile[r][cc] = raw;\n                }\n            }\n        }\n        kk[chunk * KH] = ktile;\n        c.intermediate_touches += CHUNK * CHUNK;\n    }\n    c.dispatches.push(\"a_diag_inv\");\n    c.intermediate_allocs += 2;\n    let beta_all = beta_input_all();\n    let mut a_packed = vec![[[0.0f32; CHUNK]; CHUNK]; NCHUNK * VH];\n    let mut a_inv = vec![[[[0.0f32; BLOCK]; BLOCK]; NB]; NCHUNK * VH];\n    for chunk in 0..NCHUNK {\n        let base = chunk * CHUNK;\n        let valid = (SUFFIX - base).min(CHUNK);\n        for head in 0..VH {\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for r in 0..valid {\n                for cc in 0..valid {\n                    if cc < r {\n                        tile[r][cc] = a_entry(\n                            beta_at(chunk, head, r, &beta_all),\n                            g_at(chunk, head, r, &g),\n                            g_at(chunk, head, cc, &g),\n                            kk[chunk * KH][r][cc],\n                        );\n                    }\n                }\n            }\n            a_packed[chunk * VH + head] = tile;\n            c.intermediate_touches += CHUNK * CHUNK;\n            for b in 0..NB {\n                let mut diag = [[0.0f32; BLOCK]; BLOCK];\n                for i in 0..BLOCK {\n                    for j in 0..BLOCK {\n                        diag[i][j] = tile[b * BLOCK + i][b * BLOCK + j];\n                    }\n                }\n                a_inv[chunk * VH + head][b] = unit_lower_inverse(&diag);\n                c.intermediate_touches += BLOCK * BLOCK;\n            }\n        }\n    }\n    c.dispatches.push(\"causal_inv\");\n    let mut t: Vec<Vec<f32>> = Vec::new();\n    for chunk in 0..NCHUNK {\n        for head in 0..VH {\n            let a = &a_packed[chunk * VH + head];\n            let mut t_blocks = [[[0.0f32; CHUNK]; BLOCK]; NB];\n            let mut tile = [[0.0f32; CHUNK]; CHUNK];\n            for b in 0..NB {\n                t_blocks[b] = compose_block(b, a, &a_inv[chunk * VH + head][b], &t_blocks);\n                for i in 0..BLOCK {\n                    for col in 0..CHUNK {\n                        tile[b * BLOCK + i][col] = t_blocks[b][i][col];\n                    }\n                }\n            }\n            c.intermediate_touches += CHUNK * CHUNK * 2;\n            t.push(tile.iter().flatten().copied().collect::<Vec<f32>>());\n        }\n    }\n    c.dispatches.push(\"output_and_state\");\n    (qk, t, g.concat(), c)\n}\n\n#[test]\nfn one_kernel_replaces_the_four_kernel_chain() {\n    let (_, _, _, c) = encode_fused();\n    assert_eq!(c.dispatches, vec![\"prep\", \"precompute\", \"output_and_state\"]);\n    assert_eq!(c.dispatches.len(), 3, \"the encode drops from 6 dispatches to 3\");\n    assert_eq!(c.intermediate_allocs, 0, \"kk / a_packed / a_inv are never born\");\n    assert_eq!(c.intermediate_touches, 0, \"no intermediate is written or read back\");\n}\n\n#[test]\nfn the_fused_outputs_are_bit_identical_to_the_chain() {\n    let (qk_f, t_f, g_f, _) = encode_fused();\n    let (qk_n, t_n, g_n, _) = encode_naive();\n    assert_eq!(g_f.len(), g_n.len());\n    for i in 0..g_f.len() {\n        assert_eq!(g_f[i].to_bits(), g_n[i].to_bits(), \"g {i} moved bits\");\n    }\n    for i in 0..qk_f.len() {\n        assert_eq!(qk_f[i].len(), qk_n[i].len());\n        for j in 0..qk_f[i].len() {\n            assert_eq!(qk_f[i][j].to_bits(), qk_n[i][j].to_bits(), \"qk {i}:{j} moved bits\");\n        }\n    }\n    for i in 0..t_f.len() {\n        for j in 0..t_f[i].len() {\n            assert_eq!(t_f[i][j].to_bits(), t_n[i][j].to_bits(), \"t {i}:{j} moved bits\");\n        }\n    }\n}\n\n#[test]\nfn the_fused_t_is_still_the_unit_lower_inverse() {\n    let (_, t, _, _) = encode_fused();\n    let tile: [[f32; CHUNK]; CHUNK] = t[0].chunks_exact(CHUNK).map(|r| r.try_into().unwrap()).collect::<Vec<_>>().try_into().unwrap();\n    assert_eq!(tile[0][0], 1.0);\n    for r in 0..CHUNK {\n        for cc in (r + 1)..CHUNK {\n            assert_eq!(tile[r][cc], 0.0);\n        }\n    }\n}\n\n#[test]\nfn admission_refuses_f16_and_wide_groups() {\n    assert_eq!(admit(2, Outer::Bf16), Some(\"chunked_precompute\"));\n    assert_eq!(admit(4, Outer::F32), Some(\"chunked_precompute\"));\n    assert_eq!(admit(2, Outer::F16), None, \"the f16 outer-type gate refuses\");\n    assert_eq!(admit(5, Outer::Bf16), None, \"groups_per_head > 4 refuses: recurrent fallback\");\n    assert_eq!(admit(8, Outer::F32), None);\n}\n".to_string(),
        },
    ]
}
